import { describe, it, expect, beforeEach } from 'vitest';
import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from '../app/watchlist-store';

describe('WatchlistStore ordering', () => {
  beforeEach(() => localStorage.clear());

  it('exposes unwatched items before watched ones', () => {
    const store = TestBed.inject(WatchlistStore);
    store.add({ id: 1, title: 'Watched A', release_date: '2020-01-01', poster_path: null, overview: '' });
    store.add({ id: 2, title: 'Unwatched B', release_date: '2021-01-01', poster_path: null, overview: '' });
    store.add({ id: 3, title: 'Unwatched C', release_date: '2022-01-01', poster_path: null, overview: '' });
    store.add({ id: 4, title: 'Watched D', release_date: '2023-01-01', poster_path: null, overview: '' });
    store.toggleWatched(1);
    store.toggleWatched(4);
    const items = store.items();
    const watchedIds = items.filter(i => i.watched).map(i => i.id);
    const unwatchedIds = items.filter(i => !i.watched).map(i => i.id);
    expect(items.slice(0, unwatchedIds.length).every(i => !i.watched)).toBe(true);
    expect(items.slice(unwatchedIds.length).every(i => i.watched)).toBe(true);
    expect(new Set(unwatchedIds)).toEqual(new Set([2, 3]));
    expect(new Set(watchedIds)).toEqual(new Set([1, 4]));
  });

  it('reorders when an item is toggled', () => {
    const store = TestBed.inject(WatchlistStore);
    store.add({ id: 1, title: 'A', release_date: '2020-01-01', poster_path: null, overview: '' });
    store.add({ id: 2, title: 'B', release_date: '2021-01-01', poster_path: null, overview: '' });
    store.toggleWatched(2);
    expect(store.items()[0].id).toBe(1);
    store.toggleWatched(1);
    expect(store.items().map(i => i.id)).toEqual([2, 1]);
  });
});

