import { computed, effect, Injectable, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private static orderByWatched(items: WatchItem[]): WatchItem[] {
        return [...items.filter(m => !m.watched), ...items.filter(m => m.watched)];
    }

    private _items = signal<WatchItem[]>(
        WatchlistStore.orderByWatched(JSON.parse(localStorage.getItem(this.KEY) ?? '[]'))
    );

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.watched).length)

    constructor() {
        effect(() => {
            localStorage.setItem(this.KEY, JSON.stringify(this._items()));
        });
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id) ? items : WatchlistStore.orderByWatched([...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, watched: false }])
        );
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            WatchlistStore.orderByWatched(items.map(m => m.id === id ? { ...m, watched: !m.watched } : m))
        );
    }
}

import { TestBed } from '@angular/core/testing';
import { WatchlistStore } from './watchlist-store';
import { TmdbMovie } from './movie';

function movie(id: number, title = `Movie ${id}`): TmdbMovie {
  return { id, title, poster_path: null, release_date: '2024-01-01', overview: '' };
}

function stored(items: { id: number; title: string; watched: boolean }[]) {
  localStorage.setItem('watchlist', JSON.stringify(items));
}

describe('WatchlistStore', () => {
  let service: WatchlistStore;

  beforeEach(() => {
    localStorage.removeItem('watchlist');
    TestBed.configureTestingModule({});
    service = TestBed.inject(WatchlistStore);
  });

  it('should be created', () => {
    expect(service).toBeTruthy();
  });

  it('should order unwatched before watched on load', () => {
    TestBed.resetTestingModule();
    stored([
      { id: 1, title: 'A', watched: true },
      { id: 2, title: 'B', watched: false },
      { id: 3, title: 'C', watched: true },
    ]);
    TestBed.configureTestingModule({});
    const s = TestBed.inject(WatchlistStore);
    expect(s.items().map(m => m.id)).toEqual([2, 1, 3]);
  });

  it('should keep unwatched first after add and toggleWatched', () => {
    service.add(movie(1));
    service.add(movie(2));
    service.toggleWatched(1);
    expect(service.items().map(m => m.id)).toEqual([2, 1]);

    service.toggleWatched(2);
    expect(service.items().map(m => m.id)).toEqual([1, 2]);

    service.add(movie(3));
    expect(service.items().map(m => m.id)).toEqual([3, 1, 2]);
  });

  it('should preserve relative order and update after remove', () => {
    service.add(movie(1));
    service.add(movie(2));
    service.add(movie(3));
    service.toggleWatched(1);
    service.toggleWatched(3);
    // unwatched: 2; watched: 1, 3
    expect(service.items().map(m => m.id)).toEqual([2, 1, 3]);
    service.remove(2);
    expect(service.items().map(m => m.id)).toEqual([1, 3]);
  });
});

